composition:
  authorize: "hasRole('OWNER_ADMIN')"

# Validate required fields first so a missing/blank field is a 400 with an 'errors'
# array. This step binds the body once and republishes it for BuildOwner.
validate:
  class: org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerFields
  next: checkIdentityUnique

# The single duplicate check: reject (409) only when the new owner's WHOLE derived identityKey
# (normalizedTelephone|email|householdId) equals an existing owner's. This consolidates the former
# separate telephone, email and household checks. Because the telephone is part of the key, two
# members of the same household with different telephones have different identityKeys and are both
# allowed. Reads within the same write transaction as the insert so the check and the insert see one
# consistent view.
checkIdentityUnique:
  class: org.springframework.samples.petclinic.rest.function.owner.CheckIdentityUnique
  govern: [ transaction ]
  next: checkCityCapacity

# Reject (409) when the request's city already contains 50 or more owners. Reads within the same
# write transaction as the insert so the count and the insert see one consistent view.
checkCityCapacity:
  class: org.springframework.samples.petclinic.rest.function.owner.CheckCityCapacity
  govern: [ transaction ]
  next: build

build:
  class: org.springframework.samples.petclinic.rest.function.owner.BuildOwner
  govern: [ transaction ]
  next: defaultRegistrationDate

# Resolve the effective registrationDate (supplied, else today's server date) and roll a weekend
# date forward to the next Monday, so the persisted date is always a business day. Runs before the
# daily-limit count and save so both see the adjusted date.
defaultRegistrationDate:
  class: org.springframework.samples.petclinic.rest.function.owner.DefaultRegistrationDate
  govern: [ transaction ]
  next: checkDailyLimit

# Reject (429) once 100 or more owners have already been registered on this request's adjusted
# business day (by registrationDate). Runs after the date is resolved so it counts per business day,
# within the same write transaction as the insert so the count and the insert see one consistent view.
checkDailyLimit:
  class: org.springframework.samples.petclinic.rest.function.owner.CheckDailyLimit
  govern: [ transaction ]
  next: assignCustomerCode

# Assign the '<REGION>-<HASH8>' customer code: REGION derived from the postcode (else city, else
# UNKNOWN) and HASH8 the first 8 upper-case hex chars of SHA-256(normalizedTelephone + lastName).
# A pure function of the owner's fields — no sequence numbers, so no repository read is needed.
assignCustomerCode:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignCustomerCode
  govern: [ transaction ]
  next: assignHouseholdId

# Assign the stable, shared householdId derived from the normalized last name + address, so owners
# in the same household (accepted via 'sharesHousehold') share one identifier. Runs before save so
# the id is persisted and returned.
assignHouseholdId:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignHouseholdId
  govern: [ transaction ]
  next: assignHouseholdMemberCount

# Count this owner's household (owners sharing the assigned householdId) including this new owner,
# giving the household size after this create. Runs after the householdId is assigned and within the
# write transaction so it counts only owners already persisted plus this one.
assignHouseholdMemberCount:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignHouseholdMemberCount
  govern: [ transaction ]
  next: assignNamesakeCount

# Count existing owners sharing this owner's firstName + lastName (case-insensitively). Runs before
# save within the write transaction so it counts only owners already persisted, excluding this new one.
assignNamesakeCount:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignNamesakeCount
  govern: [ transaction ]
  next: assignBulkSignupWarning

# Flag (bulkSignupWarning) when more than 80 owners have already been registered on this request's
# adjusted business day. Runs after the date is resolved and within the same write transaction as the
# insert so the count reflects only owners already persisted (excluding this new one).
assignBulkSignupWarning:
  class: org.springframework.samples.petclinic.rest.function.owner.AssignBulkSignupWarning
  govern: [ transaction ]
  next: save

save:
  class: org.springframework.samples.petclinic.rest.function.owner.SaveOwner
  govern: [ transaction ]
  next: audit

# On successful create, emit an audit line via the dedicated AUDIT logger carrying the
# owner id, customerCode and registrationDate. Runs after save so the generated id exists.
audit:
  class: org.springframework.samples.petclinic.rest.function.owner.AuditOwnerCreated
  govern: [ transaction ]
  next: respond

respond:
  class: org.springframework.samples.petclinic.rest.function.owner.RespondWithOwnerCreated
  govern: [ transaction ]
=== OwnerMapper ===
package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
                    + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
    @Mapping(target = "membershipLevel", expression = "java(OwnerMapper.membershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Derives the owner's {@code identityKey}, the single key all duplicate detection is expressed
     * through: {@code '<normalizedTelephone>|<email or empty>|<householdId>'}
     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity}).
     */
    default String identityKey(Owner owner) {
        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity
                .identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /**
     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
     * otherwise {@code 'PHONE'}.
     */
    default String contactPreference(Owner owner) {
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        return hasEmail ? "EMAIL" : "PHONE";
    }

    /**
     * Derives the owner's locality (region) from the region-and-hash {@code customerCode}: it is the
     * {@code REGION} prefix of {@code '<REGION>-<HASH8>'} (see
     * {@link org.springframework.samples.petclinic.rest.function.owner.CustomerCode}). When the code is
     * absent it falls back to computing the region directly from the postcode range (NSW 2000-2099,
     * VIC 3000-3099, QLD 4000-4099) then the city table, yielding {@code 'UNKNOWN'} when neither
     * resolves. Sharing the region with the identity keeps locality and customerCode consistent.
     */
    default String locality(Owner owner) {
        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCode
                .regionOf(owner.getCustomerCode());
        if (region != null) {
            return region;
        }
        return org.springframework.samples.petclinic.rest.function.owner.CustomerCode
                .region(owner.getPostcode(), owner.getCity());
    }

    /**
     * Derives the owner's membership level from 1 to 3: starting at 1, plus 1 when an email is
     * present, plus 1 when {@code namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
     */
    static Integer membershipLevel(Owner owner) {
        int level = 1;
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        if (hasEmail) {
            level++;
        }
        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        if (noNamesakes) {
            level++;
        }
        return Math.min(level, 3);
    }

    /**
     * Derives the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
     * last two digits of the registrationDate year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Returns {@code null}
     * when either source field is absent, so owners without a customerCode or registrationDate map cleanly.
     */
    default String membershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return owner.getCustomerCode() + "-M"
                + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
    }

    /**
     * Derives the owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
     * digits contained in the {@code customerCode}. Returns {@code null} when the customerCode is
     * absent, so owners without a customerCode map cleanly.
     */
    default Integer checkDigit(Owner owner) {
        String customerCode = owner.getCustomerCode();
        if (customerCode == null) {
            return null;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = customerCode.length() - 1; i >= 0; i--) {
            char c = customerCode.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
    @Mapping(target = "householdId", ignore = true)
    @Mapping(target = "namesakeCount", ignore = true)
    @Mapping(target = "householdMemberCount", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

